/** Public entry point for the data-grid-io add-on — the only module consumers should import from. */

export { exportGrid, buildXlsx, buildExportRows, buildExportHeaders, quoteCsvField, rowsToCsv, downloadBlob, type ExportGridOptions, type BuildXlsxOptions, type BuildExportRowsOptions } from "./export-grid";
export { useDataGridExport, type UseDataGridExportResult } from "./use-data-grid-export";

export { printGrid, type PrintGridOptions } from "./print-grid";
export { useDataGridPrint, type UseDataGridPrintResult } from "./use-data-grid-print";
export { DataGridPrintButton, type DataGridPrintButtonProps } from "./print-button";

export { parseImportFile, DEFAULT_IMPORT_LIMITS, type ParsedImportFile, type ParseImportFileOptions, type ImportLimits, type CsvDelimiter } from "./parse-import-file";
export { matchImportColumns, applyImportOptions, type ImportDefaults } from "./match-import-column";
export { buildImportedRows, IMPORT_CANCELLED_MESSAGE, type ImportColumnMapping, type BuildImportedRowsOptions, type BuildImportedRowsResult, type ImportRejectedCell } from "./build-imported-rows";
export {
  useDataGridImportPreview,
  IMPORT_PREVIEW_ROW_COUNT,
  type ImportFileState,
  type ImportTargetColumn,
  type ImportErrorKey,
  type UseDataGridImportPreviewOptions,
  type UseDataGridImportPreviewResult,
} from "./use-data-grid-import";
export { DataGridImportDialog, type DataGridImportDialogProps } from "./import-dialog";

export { DataGridExportButton, type DataGridExportButtonProps } from "./export-button";
export { DataGridImportButton, type DataGridImportButtonProps } from "./import-button";

import { getCellValue, sanitizeFormulaCell, type AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, displayText, getSelectedViewRows, isDev, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { CsvDelimiter } from "./parse-import-file";

/** Longest cell text an Excel worksheet holds; XLSX export and print cut longer text to it. */
export const MAX_CELL_TEXT = 32_767;

/** Options for {@link exportGrid}. */
export type ExportGridOptions = {
  /** 'xlsx' via lazily-imported hucre, or hand-rolled RFC4180 'csv' (default). */
  format?: "xlsx" | "csv";
  /** 'view' (default) exports the current sort/filter order; 'all' ignores view order and exports every row in `data` order; 'selection' exports only the selected rows, in view order. */
  scope?: "view" | "all" | "selection";
  /** Whether to emit a header row; default true. */
  includeHeaders?: boolean;
  /** CSV field delimiter; default ','. Ignored for xlsx. */
  csvDelimiter?: CsvDelimiter;
  /**
   * Prefix the CSV with a UTF-8 BOM (`\uFEFF`); default `true`. Excel only detects UTF-8 when the
   * file starts with a BOM — without it, umlauts and other non-ASCII characters open as mojibake.
   * Set `false` when a downstream consumer chokes on a leading BOM character.
   */
  csvBom?: boolean;
  /**
   * Prefix formula-like CSV cells (leading `=`, `+`, `-`, `@`, TAB, or CR; plain numbers exempt) with
   * a single quote so Excel/LibreOffice/Sheets read them as text instead of executing them;
   * default `true`. Set `false` when a downstream consumer expects the raw string.
   * XLSX exports are unaffected (string cells never run as formulas).
   */
  sanitizeFormulas?: boolean;
  /** Download file name, without extension; default 'export'. */
  fileName?: string;
  /** Name of the single sheet inside the xlsx file; default 'Sheet1'. Ignored for csv. An invalid Excel sheet name (over 31 characters, `[]:*?/\`, `History`) rejects. */
  workbookName?: string;
  /** Caps the number of data rows exported (the header row is not counted); when the scope exceeds the cap, the export is truncated with a dev-only warning. */
  maxRows?: number;
};

const NEEDS_QUOTING_DEFAULT = /["\r\n]/;

/** Quotes one RFC4180 CSV field when it contains the delimiter, a quote, or a line break; doubles internal quotes. */
export function quoteCsvField(value: string, delimiter: string): string {
  const needsQuoting = value.includes(delimiter) || NEEDS_QUOTING_DEFAULT.test(value);
  if (!needsQuoting) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/**
 * Joins rows into an RFC4180 CSV string (CRLF line endings), quoting fields as needed. With
 * `sanitizeFormulas` (default `true`), formula-like fields get a leading `'` first (see `sanitizeFormulaCell`).
 */
export function rowsToCsv(rows: readonly (readonly string[])[], delimiter: string, sanitizeFormulas = true): string {
  // sanitize before quoting: the apostrophe prefix itself never needs quoting
  const field = (value: string) => quoteCsvField(sanitizeFormulas ? sanitizeFormulaCell(value) : value, delimiter);
  return rows.map((row) => row.map(field).join(delimiter)).join("\r\n");
}

/** Options for {@link buildExportRows}. */
export type BuildExportRowsOptions = {
  /** Cell text source: `'export'` uses the cell type's `toText` (CSV/XLSX), `'display'` uses `toDisplayText ?? toText` (print). Default `'export'`. */
  text?: "export" | "display";
  /** Caps the number of data rows built (the header row is not counted). */
  maxRows?: number;
};

/**
 * Resolves the data indices a scope covers (lazy holes excluded): `'view'` walks `viewIndex`
 * (current sort/filter order), `'all'` walks `data` as-is, `'selection'` walks only the selected
 * rows in view order.
 */
export function exportDataIndices(state: DataGridReadState, scope: "view" | "all" | "selection"): number[] {
  const scoped =
    scope === "all"
      ? state.data.map((_, i) => i)
      : scope === "selection"
        ? getSelectedViewRows(state.selection, { checkedRowsOnly: state.keepCheckedRows }).map((viewRow) => state.viewIndex[viewRow]!)
        : state.viewIndex;
  // lazy grids keep `data` sparse: skip holes before any accessor runs
  return scoped.filter((dataRowIndex) => state.data[dataRowIndex] !== undefined);
}

/**
 * Resolves the rows to export via the cell-type pipeline, in the requested `scope` order. With
 * `options.text: "display"` the cell type's display text (`toDisplayText ?? toText`) is used; the
 * default `'export'` uses `toText` (CSV/XLSX). Every scope emits all visible columns, so a
 * row-shaped export always matches its header row. Hole rows (unloaded indices of a lazy grid's
 * sparse `data`) are skipped in every scope. `options.maxRows` caps the number of rows built.
 */
export function buildExportRows(state: DataGridReadState, scope: "view" | "all" | "selection", options: BuildExportRowsOptions = {}): string[][] {
  const { text = "export", maxRows } = options;
  const dataIndices = exportDataIndices(state, scope);
  return buildRowsAt(state, maxRows === undefined ? dataIndices : dataIndices.slice(0, maxRows), text);
}

function buildRowsAt(state: DataGridReadState, dataIndices: readonly number[], text: "export" | "display"): string[][] {
  return dataIndices.map((dataRowIndex) => {
    const row = state.data[dataRowIndex];
    return state.visibleColumns.map((column) => {
      const cellType = state.cellTypes[column.type ?? "text"];
      const value = getCellValue<unknown, AnyColumnDef>(row, column);
      return cellType ? (text === "display" ? displayText(cellType, value, column.options) : cellType.toText(value, column.options)) : "";
    });
  });
}

/** Builds at most `maxRows` rows, with a dev-only warning when the scope exceeds the cap. */
function buildCappedExportRows(state: DataGridReadState, scope: "view" | "all" | "selection", maxRows: number | undefined): string[][] {
  if (maxRows !== undefined) {
    const total = exportDataIndices(state, scope).length;
    if (total > maxRows && isDev()) console.warn(`[data-grid-io] export truncated to ${maxRows} of ${total} rows (maxRows)`);
  }
  return buildExportRows(state, scope, { maxRows });
}

/** Header row text for each visible column, in the same order `buildExportRows` emits cells. */
export function buildExportHeaders(state: DataGridReadState): string[] {
  return state.visibleColumns.map((column) => columnLabelText(column));
}

/** Triggers a browser download of `blob` named `fileName`, via a temporary anchor + object URL (revoke deferred — see below). */
export function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.style.display = "none";
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  // Firefox/Safari read the blob URL asynchronously after click(); revoking on the same tick can truncate the download.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** Options for {@link buildXlsx}. */
export type BuildXlsxOptions = {
  /** Row scope, same semantics as {@link ExportGridOptions.scope}; default 'view'. */
  scope?: "view" | "all" | "selection";
  /** Whether to emit a header row; default true. */
  includeHeaders?: boolean;
  /** Name of the single sheet inside the workbook; default 'Sheet1'. An invalid Excel sheet name (over 31 characters, `[]:*?/\`, `History`) rejects. */
  workbookName?: string;
  /** Same row cap as {@link ExportGridOptions.maxRows}. */
  maxRows?: number;
};

/**
 * Builds an xlsx `Blob` from the grid's state without triggering a download — for server uploads
 * or inspecting the workbook before it leaves the browser. Values go through each column's cell
 * type `toText` like `exportGrid` and land as string cells, never formulas; hucre loads lazily.
 */
export async function buildXlsx(state: DataGridReadState, options: BuildXlsxOptions = {}): Promise<Blob> {
  const { scope = "view", includeHeaders = true, workbookName = "Sheet1", maxRows } = options;
  const rows = buildCappedExportRows(state, scope, maxRows);
  const table = includeHeaders ? [buildExportHeaders(state), ...rows] : rows;

  const cutRows = table.map((row) => row.map((text) => (text.length > MAX_CELL_TEXT ? text.slice(0, MAX_CELL_TEXT) : text)));

  const { writeXlsx } = await import("./xlsx-writer");
  const bytes = await writeXlsx({ sheets: [{ name: workbookName, rows: cutRows }] });
  // hucre types its output as ArrayBufferLike, but writeXlsx never returns a SharedArrayBuffer view
  return new Blob([bytes as Uint8Array<ArrayBuffer>], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
}

/**
 * Serializes the grid to CSV or XLSX and triggers a download. Values always go through each
 * column's cell type `toText` (never raw values), so clipboard/export fidelity matches. hucre is
 * loaded lazily (dynamic `import()`) so the dependency never loads for CSV-only consumers.
 */
export async function exportGrid(state: DataGridReadState, options: ExportGridOptions = {}): Promise<void> {
  const { format = "csv", scope = "view", includeHeaders = true, csvDelimiter = ",", csvBom = true, sanitizeFormulas = true, fileName = "export", workbookName, maxRows } = options;
  if (format === "csv") {
    const rows = buildCappedExportRows(state, scope, maxRows);
    const table = includeHeaders ? [buildExportHeaders(state), ...rows] : rows;
    const csv = (csvBom ? "\uFEFF" : "") + rowsToCsv(table, csvDelimiter, sanitizeFormulas);
    downloadBlob(new Blob([csv], { type: "text/csv;charset=utf-8;" }), `${fileName}.csv`);
    return;
  }

  const blob = await buildXlsx(state, { scope, includeHeaders, workbookName, maxRows });
  downloadBlob(blob, `${fileName}.xlsx`);
}

"use client";

import { useCallback } from "react";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { exportGrid, type ExportGridOptions } from "./export-grid";

/** Public export trigger returned by {@link useDataGridExport}. */
export type UseDataGridExportResult = {
  /** Serializes the grid per `options` and triggers a browser download. */
  exportGrid: (options?: ExportGridOptions) => Promise<void>;
};

/** Wires {@link exportGrid} to the grid's store instance, for toolbar buttons and custom triggers. */
export function useDataGridExport(): UseDataGridExportResult {
  const storeApi = useDataGridStoreApi();

  const run = useCallback(
    (options?: ExportGridOptions) => exportGrid(storeApi.getState(), options),
    [storeApi],
  );

  return { exportGrid: run };
}

"use client";

import type { ReactNode } from "react";
import { Download } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useDataGridExport } from "./use-data-grid-export";
import type { ExportGridOptions } from "./export-grid";

type ExportFormat = "xlsx" | "csv";

/** Props for {@link DataGridExportButton}. */
export type DataGridExportButtonProps = {
  className?: string;
  /** The formats the button offers; one format exports on click, several open a menu. Default `["xlsx", "csv"]`. */
  formats?: readonly ExportFormat[];
  /** Export options applied to both formats besides `format` itself; default `{ scope: 'view', includeHeaders: true }`. */
  options?: Omit<ExportGridOptions, "format">;
  /** Receives the rejection when an export fails; without it, the failure logs a dev-only warning. */
  onError?: (error: unknown, format: ExportFormat) => void;
};

/**
 * Toolbar-slot export trigger: a ghost icon button opening a dropdown of xlsx/csv, wired to
 * {@link useDataGridExport}. `size-8` + ghost variant matches the toolbar's other icon buttons.
 */
export function DataGridExportButton(props: DataGridExportButtonProps): ReactNode {
  const { className, formats = ["xlsx", "csv"], options, onError } = props;
  const labels = useDataGridLabels();
  const { exportGrid } = useDataGridExport();

  const runExport = (format: ExportFormat) => {
    exportGrid({ ...options, format }).catch((error: unknown) => {
      if (onError) {
        onError(error, format);
        return;
      }
      if (isDev()) console.warn(`[data-grid-io] ${format} export failed`, error);
    });
  };

  const triggerButton = (onClick?: () => void) => (
    <Button type="button" variant="ghost" size="icon" className={className} aria-label={labels.io.exportButtonAriaLabel} onClick={onClick}>
      <Download />
    </Button>
  );

  if (formats.length === 1) return triggerButton(() => runExport(formats[0]!));

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={triggerButton()} />
      <DropdownMenuContent align="start">
        {formats.includes("xlsx") && (
          <DropdownMenuItem onClick={() => runExport("xlsx")}>
            {labels.io.exportXlsx}
          </DropdownMenuItem>
        )}
        {formats.includes("csv") && (
          <DropdownMenuItem onClick={() => runExport("csv")}>
            {labels.io.exportCsv}
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_CELL_TEXT, buildExportHeaders, buildExportRows, exportDataIndices } from "./export-grid";

/** Default number of rows printed when `maxRows` is not given. */
const DEFAULT_PRINT_MAX_ROWS = 10_000;
/** Hard ceiling on the printed table's cell count (a multi-million-cell DOM table hangs the print dialog). */
const PRINT_CELL_CEILING = 500_000;
/** Fallback removal (ms) for the print iframe when the window's `afterprint` never fires. */
const PRINT_FALLBACK_MS = 60_000;

/** Page sizes for {@link PrintGridOptions.pageSize}. */
export type PrintPageSize = "A3" | "A4" | "Letter" | "Legal";

/** CSS `@page` size keyword per page size. */
const PAGE_SIZE_CSS: Record<PrintPageSize, string> = { A3: "A3", A4: "A4", Letter: "letter", Legal: "legal" };

/** Options for {@link printGrid}. */
export type PrintGridOptions = {
  /** Which rows to print; default `"view"` (the current sort and filter order). */
  scope?: "view" | "all" | "selection";
  /** Printed as an `<h1>` heading and the document title. */
  title?: string;
  /** Emit a `<thead>` header row; default `true`. */
  includeHeaders?: boolean;
  /** Page size of the printed PDF; default `"A4"`. */
  pageSize?: PrintPageSize;
  /** Page orientation; default: `landscape` above 6 visible columns, else `portrait`. */
  orientation?: "portrait" | "landscape";
  /** Cap on the rows printed (the header row is not counted); default 10,000, further cut by the 500,000-cell ceiling. */
  maxRows?: number;
};

let openIframe: HTMLIFrameElement | null = null;
let fallbackTimer: ReturnType<typeof setTimeout> | null = null;

/** Removes the currently open print iframe and clears its fallback timer. */
function removeOpenIframe(): void {
  if (fallbackTimer !== null) {
    clearTimeout(fallbackTimer);
    fallbackTimer = null;
  }
  openIframe?.remove();
  openIframe = null;
}

function cutText(text: string): string {
  return text.length > MAX_CELL_TEXT ? text.slice(0, MAX_CELL_TEXT) : text;
}

function printCss(pageSize: string, orientation: "portrait" | "landscape"): string {
  return [
    `@page { size: ${pageSize} ${orientation}; margin: 12mm; }`,
    "body { font: 10pt/1.4 system-ui, sans-serif; color: #000; }",
    "h1 { font-size: 14pt; margin: 0 0 8px; }",
    "table { border-collapse: collapse; width: 100%; }",
    "thead { display: table-header-group; }",
    "tr { break-inside: avoid; }",
    "th, td { border: 1px solid #999; padding: 2px 6px; text-align: left; }",
    "th { font-weight: 600; }",
    "p { margin: 8px 0 0; }",
  ].join("\n");
}

/**
 * Prints the grid's rows as a plain paged table: the rows are resolved through the cell-type
 * pipeline's display text (`toDisplayText ?? toText`), built into a hidden, sandboxed iframe's
 * document with `textContent` only (no value ever passes an HTML parser), and the browser print
 * dialog is opened — its "Save as PDF" produces the PDF. Visible columns only, in view order;
 * lazy holes and hidden columns never print. `options.maxRows` caps the rows (default 10,000,
 * further cut to fit the 500,000-cell ceiling); when the cap cut the output, the table ends
 * with a truncation note. The iframe is removed on `afterprint` (with a 60 s fallback timer),
 * and a second call while one is open replaces the first. No-op without a DOM (SSR).
 */
export function printGrid(state: DataGridReadState, options: PrintGridOptions = {}): void {
  if (typeof document === "undefined") return;
  removeOpenIframe();

  const scope = options.scope ?? "view";
  const includeHeaders = options.includeHeaders ?? true;
  const colCount = state.visibleColumns.length;
  const maxRows = Math.min(options.maxRows ?? DEFAULT_PRINT_MAX_ROWS, Math.floor(PRINT_CELL_CEILING / Math.max(colCount, 1)));
  const total = exportDataIndices(state, scope).length;
  const rows = buildExportRows(state, scope, { text: "display", maxRows });
  const headers = buildExportHeaders(state);
  const orientation = options.orientation ?? (colCount > 6 ? "landscape" : "portrait");
  // Untyped callers can pass any string; only the fixed map reaches the CSS.
  const requestedSize = options.pageSize ?? "A4";
  const pageSize = Object.hasOwn(PAGE_SIZE_CSS, requestedSize) ? PAGE_SIZE_CSS[requestedSize] : "A4";

  const iframe = document.createElement("iframe");
  // attribute, not the sandbox IDL property: jsdom reflects the IDL property incompletely
  iframe.setAttribute("sandbox", "allow-same-origin allow-modals");
  // zero-size and off-screen: the iframe exists only to host the print document
  iframe.style.position = "fixed";
  iframe.style.width = "0";
  iframe.style.height = "0";
  iframe.style.border = "0";
  iframe.style.visibility = "hidden";
  document.body.append(iframe);

  const doc = iframe.contentDocument;
  const win = iframe.contentWindow;
  if (!doc || !win) {
    iframe.remove();
    return;
  }

  doc.title = options.title ?? "";
  const meta = doc.createElement("meta");
  meta.httpEquiv = "Content-Security-Policy";
  meta.content = "default-src 'none'; style-src 'unsafe-inline'";
  const style = doc.createElement("style");
  style.textContent = printCss(pageSize, orientation);
  doc.head.append(meta, style);
  if (options.title) {
    const heading = doc.createElement("h1");
    heading.textContent = options.title;
    doc.body.append(heading);
  }

  const table = doc.createElement("table");
  if (includeHeaders) {
    const thead = doc.createElement("thead");
    const headerRow = doc.createElement("tr");
    for (const header of headers) {
      const th = doc.createElement("th");
      th.scope = "col";
      th.textContent = cutText(header);
      headerRow.append(th);
    }
    thead.append(headerRow);
    table.append(thead);
  }
  const tbody = doc.createElement("tbody");
  for (const row of rows) {
    const tr = doc.createElement("tr");
    for (let i = 0; i < row.length; i++) {
      const td = doc.createElement("td");
      const align = state.cellTypes[state.visibleColumns[i]!.type ?? "text"]?.align;
      if (align) td.style.textAlign = align;
      td.textContent = cutText(row[i]!);
      tr.append(td);
    }
    tbody.append(tr);
  }
  table.append(tbody);
  doc.body.append(table);
  if (rows.length < total) {
    const note = doc.createElement("p");
    note.textContent = state.labels.io.printTruncated(rows.length, total);
    doc.body.append(note);
  }

  const cleanup = () => {
    win.removeEventListener("afterprint", cleanup);
    removeOpenIframe();
  };
  win.addEventListener("afterprint", cleanup);
  fallbackTimer = setTimeout(cleanup, PRINT_FALLBACK_MS);
  openIframe = iframe;
  win.print();
}

"use client";

import { useCallback } from "react";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { printGrid, type PrintGridOptions } from "./print-grid";

/** Public print trigger returned by {@link useDataGridPrint}. */
export type UseDataGridPrintResult = {
  /** Prints the grid's rows as a paged table and opens the browser print dialog. */
  printGrid: (options?: PrintGridOptions) => void;
};

/** Wires {@link printGrid} to the grid's store instance, for toolbar buttons and custom triggers. */
export function useDataGridPrint(): UseDataGridPrintResult {
  const storeApi = useDataGridStoreApi();

  const run = useCallback(
    (options?: PrintGridOptions) => printGrid(storeApi.getState(), options),
    [storeApi],
  );

  return { printGrid: run };
}

"use client";

import type { ReactNode } from "react";
import { Printer } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { Button } from "@/components/ui/button";
import { useDataGridPrint } from "./use-data-grid-print";
import type { PrintGridOptions } from "./print-grid";

/** Props for {@link DataGridPrintButton}. */
export type DataGridPrintButtonProps = {
  className?: string;
  /** Print options applied to the pass; default `{ scope: "view", includeHeaders: true }`. */
  options?: PrintGridOptions;
};

/**
 * Toolbar-slot print trigger: opens the browser print dialog with the grid's rows as a plain
 * paged table (the dialog's "Save as PDF" produces the PDF). `size-8` + ghost variant matches
 * the toolbar's other icon buttons.
 */
export function DataGridPrintButton(props: DataGridPrintButtonProps): ReactNode {
  const { className, options } = props;
  const labels = useDataGridLabels();
  const { printGrid } = useDataGridPrint();

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className={className}
      aria-label={labels.io.printButtonAriaLabel}
      onClick={() => printGrid(options)}
    >
      <Printer />
    </Button>
  );
}

import Papa from "papaparse";
import type { CellValue } from "hucre";

/** CSV delimiter choices exposed in the import dialog; `undefined` means auto-detect. */
export type CsvDelimiter = "," | ";" | "\t";

/**
 * Default bounds for every import. Unbounded parsing is a memory/CPU DoS vector: a tiny xlsx with
 * two far-apart cells expands to millions of cells. File size is checked before the file is read;
 * the row, column, and cell caps are checked against the real cell extent before any conversion
 * (xlsx/xls) or right after the parse (CSV). A file over a cap is rejected, never truncated.
 */
export const DEFAULT_IMPORT_LIMITS = {
  /** Maximum file size in bytes; default 50 MB. */
  maxFileBytes: 50 * 1024 * 1024,
  /** Maximum rows, header row included; default 1,000,000. */
  maxRows: 1_000_000,
  /** Maximum columns; default 1,000. */
  maxColumns: 1_000,
  /** Maximum cells, counted as rows times columns of the imported rectangle; default 5,000,000. */
  maxCells: 5_000_000,
  /** Maximum unpacked size of one xlsx part (a worksheet, the shared strings); default 256 MiB, and no more than `maxCells` times 10 bytes plus 1 MiB. */
  maxDecompressedBytes: 256 * 1024 * 1024,
} as const;

/** Error message {@link parseImportFile} throws for a file over `maxFileBytes`. */
export const FILE_TOO_LARGE_MESSAGE = "file-too-large";

/** Error message {@link parseImportFile} throws when one part of an xlsx file (a worksheet, the shared strings) unpacks to more than the part cap, a lower `maxDecompressedBytes` or `maxCells` times 10 bytes plus 1 MiB. */
export const PART_TOO_LARGE_MESSAGE = "part-too-large";

/** Error message {@link parseImportFile} throws when the grid exceeds `maxRows`, `maxColumns`, or `maxCells`. */
export const IMPORT_TOO_MANY_CELLS_MESSAGE = "import-too-many-cells";

/** Error message {@link parseImportFile} throws for an Excel file that is neither xlsx nor BIFF8 xls, e.g. an HTML table, Excel 2003 XML, or Excel 5.0/95. */
export const UNSUPPORTED_EXCEL_FORMAT_MESSAGE = "unsupported-excel-format";

/** Import bounds; each omitted field falls back to {@link DEFAULT_IMPORT_LIMITS}. A file over any bound is rejected, never truncated. */
export type ImportLimits = {
  /** Reject files above this size (bytes) before the file is read; default 50 MB. */
  maxFileBytes?: number;
  /** Maximum rows, header row included; default 1,000,000. */
  maxRows?: number;
  /** Maximum columns; default 1,000. */
  maxColumns?: number;
  /** Maximum rows times columns of the imported rectangle; default 5,000,000. */
  maxCells?: number;
  /** Reject an xlsx whose parts (a worksheet, the shared strings) unpack to more than this many bytes; default 256 MiB, and no more than `maxCells` times 10 bytes plus 1 MiB. Stops zip bombs. */
  maxDecompressedBytes?: number;
};

/** Options for {@link parseImportFile}. */
export type ParseImportFileOptions = ImportLimits & {
  /** Overrides CSV delimiter auto-detection; ignored for xlsx/xls. */
  csvDelimiter?: CsvDelimiter;
  /** For xlsx/xls: import this sheet by name instead of the first; rejects when the workbook has no sheet by that name. Ignored for CSV. */
  sheetName?: string;
};

type GridLimits = Required<Pick<ImportLimits, "maxRows" | "maxColumns" | "maxCells">>;
type ExcelLimits = GridLimits & Required<Pick<ImportLimits, "maxDecompressedBytes">>;

/** Throws the too-many-cells error when a `rows` by `columns` rectangle breaks any cap. */
function assertWithinLimits(rows: number, columns: number, limits: GridLimits): void {
  if (rows > limits.maxRows || columns > limits.maxColumns || rows * columns > limits.maxCells) {
    throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  }
}

/** Normalized parse result: a plain 2D grid of strings, header row (if any) included at `rows[0]`. */
export type ParsedImportFile = {
  rows: string[][];
  /** Delimiter actually used (auto-detected or overridden); undefined for xlsx/xls. */
  delimiter?: CsvDelimiter;
  /** Every sheet name in the workbook. Undefined for CSV, or for a workbook with no sheets. */
  sheetNames?: string[];
  /** The sheet `rows` came from — the `sheetName` option, or the first sheet. Undefined for CSV. */
  sheetName?: string;
};

function isCsvFile(file: File): boolean {
  const name = file.name.toLowerCase();
  return name.endsWith(".csv") || name.endsWith(".tsv") || file.type === "text/csv" || file.type === "text/tab-separated-values";
}

function isExcelFile(file: File): boolean {
  const name = file.name.toLowerCase();
  return name.endsWith(".xlsx") || name.endsWith(".xls");
}

/** Characters papaparse sees when it guesses the delimiter and the newline. */
const CSV_SAMPLE_CHARS = 1024 * 1024;

/** The newline papaparse would guess: whichever of `\n`, `\r\n`, or `\r` ends the first line. */
function detectNewline(sample: string): "\n" | "\r\n" | "\r" {
  const cr = sample.indexOf("\r");
  const lf = sample.indexOf("\n");
  if (cr === -1 || (lf !== -1 && lf < cr)) return "\n";
  return sample[cr + 1] === "\n" ? "\r\n" : "\r";
}

/**
 * Checks the rows and the widest row against the limits without building a field. The counts
 * are upper bounds of papaparse's: it leaves a quoted field only at a quote before a delimiter or newline.
 * This mirrors the parser on purpose: papaparse has no row or cell limit option, and its parse
 * materializes a whole row at once. A regression test pins the counts against papaparse.
 */
function assertCsvWithinLimits(text: string, delimiter: string, newline: string, limits: GridLimits): void {
  const delimiterCode = delimiter.charCodeAt(0);
  const newlineCode = newline.charCodeAt(0);
  let rows = 0;
  let columns = 0;
  let fields = 1;
  let lineLength = 0;
  let inQuotes = false;
  let fieldStart = true;
  const endLine = () => {
    if (lineLength > 0) {
      rows += 1;
      if (fields > columns) columns = fields;
      assertWithinLimits(rows, columns, limits);
    }
    fields = 1;
    lineLength = 0;
    fieldStart = true;
  };
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (inQuotes) {
      lineLength += 1;
      if (code !== 34) continue;
      if (text.charCodeAt(i + 1) === 34) i += 1;
      else inQuotes = false;
      continue;
    }
    if (code === newlineCode && text.startsWith(newline, i)) {
      endLine();
      i += newline.length - 1;
      continue;
    }
    lineLength += 1;
    if (code === delimiterCode) {
      fields += 1;
      if (fields > limits.maxColumns) assertWithinLimits(rows + 1, fields, limits);
      fieldStart = true;
      continue;
    }
    if (fieldStart && code === 34) inQuotes = true;
    fieldStart = false;
  }
  endLine();
}

/** Parses CSV text with papaparse; delimiter auto-detected unless `csvDelimiter` overrides it. The limits run before the parse, which builds a whole row at once. */
function parseCsvText(text: string, csvDelimiter: CsvDelimiter | undefined, limits: GridLimits): ParsedImportFile {
  const sample = text.slice(0, CSV_SAMPLE_CHARS);
  const newline = detectNewline(sample);
  const delimiter =
    csvDelimiter ?? ((Papa.parse<string[]>(sample, { preview: 10, newline, skipEmptyLines: true }).meta.delimiter as CsvDelimiter | undefined) || ",");
  assertCsvWithinLimits(text, delimiter, newline, limits);
  const result = Papa.parse<string[]>(text, { delimiter, newline, skipEmptyLines: true });
  return { rows: result.data.map((row) => row.map((cell) => cell ?? "")), delimiter };
}

/** Aborts the file read; rejected parses surface as an AbortError the caller can ignore. */
function abortError(): DOMException {
  return new DOMException("Aborted", "AbortError");
}

const ZIP_SIGNATURE = [0x50, 0x4b, 0x03, 0x04];
const OLE2_SIGNATURE = [0xd0, 0xcf, 0x11, 0xe0];

function hasSignature(bytes: Uint8Array, signature: readonly number[]): boolean {
  return signature.every((byte, index) => bytes[index] === byte);
}

/** The smallest cell hucre stores in a sparse read, a styled empty cell `<c s="0"/>`; each costs far more heap than XML. */
const SMALLEST_CELL_XML_BYTES = 10;

/** Room in one part for everything but cells: columns, merges, validations, formatting rules. */
const PART_OVERHEAD_BYTES = 1024 * 1024;

const UNREADABLE_ZIP_MESSAGE = "unreadable-zip";

const ZIP64_SENTINEL = 0xffffffff;

/** The largest unpacked size any one part of an xlsx may have: bounds the cells a part can hold. */
function partCap(limits: ExcelLimits): number {
  return Math.min(limits.maxDecompressedBytes, limits.maxCells * SMALLEST_CELL_XML_BYTES + PART_OVERHEAD_BYTES);
}

/**
 * Rejects a zip with any entry whose stored or declared size exceeds `cap`. Reads only the central directory,
 * and fails closed: an unreadable directory or a ZIP64 marker rejects. Hucre bounds what it inflates itself,
 * but not stored entries.
 */
function assertEntriesWithin(bytes: Uint8Array, cap: number): void {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const lowest = Math.max(0, bytes.length - 22 - 0xffff);
  let end = bytes.length - 22;
  while (end >= lowest && view.getUint32(end, true) !== 0x06054b50) end--;
  if (end < lowest) throw new Error(UNREADABLE_ZIP_MESSAGE);
  const count = view.getUint16(end + 10, true);
  let offset = view.getUint32(end + 16, true);
  if (count === 0xffff || view.getUint32(end + 12, true) === ZIP64_SENTINEL || offset === ZIP64_SENTINEL) throw new Error(PART_TOO_LARGE_MESSAGE);
  for (let i = 0; i < count; i++) {
    if (offset + 46 > bytes.length || view.getUint32(offset, true) !== 0x02014b50) throw new Error(UNREADABLE_ZIP_MESSAGE);
    const compressedSize = view.getUint32(offset + 20, true);
    const uncompressedSize = view.getUint32(offset + 24, true);
    if (compressedSize > cap || uncompressedSize > cap || compressedSize === ZIP64_SENTINEL || uncompressedSize === ZIP64_SENTINEL) throw new Error(PART_TOO_LARGE_MESSAGE);
    offset += 46 + view.getUint16(offset + 28, true) + view.getUint16(offset + 30, true) + view.getUint16(offset + 32, true);
  }
}

type HucreReader = typeof import("./xlsx-reader");
type FormatValue = HucreReader["formatValue"];
type CellVisitor = (row: number, col: number, value: CellValue, numFmt: string | undefined) => void;

/** A date without a number format (xls, ISO cells): ISO date, plus the time when it is not midnight. */
function isoDateText(date: Date): string {
  if (Number.isNaN(date.getTime())) return "";
  const iso = date.toISOString();
  return iso.endsWith("T00:00:00.000Z") ? iso.slice(0, 10) : iso.slice(0, 19).replace("T", " ");
}

/** Excel's own limit on a number format's length; hucre's format scanning grows quadratically past it. */
const MAX_NUMBER_FORMAT_LENGTH = 255;

/** A fraction denominator of four or more placeholders: hucre searches every denominator up to 10^n, about a second per cell at n = 9. */
const WIDE_FRACTION_DENOMINATOR = /\/[?#0]{4}/;

/** The format as hucre's fraction test sees it: conditions, colors, locales, and fill codes stripped, literals masked. */
function fractionView(numFmt: string): string {
  return numFmt
    .replace(/\[[<>=!]+-?\d+(?:\.\d+)?\]/g, "")
    .replace(/\[(?:Black|Blue|Cyan|Green|Magenta|Red|White|Yellow|Color\s*\d+)\]/gi, "")
    .replace(/\[\$[^\]]*\]/g, "")
    .replace(/[_*]./g, "")
    .replace(/"[^"]*"?|\\[\s\S]?/g, "\0");
}

function isSafeNumberFormat(numFmt: string): boolean {
  return numFmt.length <= MAX_NUMBER_FORMAT_LENGTH && !WIDE_FRACTION_DENOMINATOR.test(fractionView(numFmt));
}

/** The number format's rendering, or `undefined` when the format is unsafe or hucre cannot apply it. */
function formattedText(value: CellValue, numFmt: string | undefined, formatValue: FormatValue): string | undefined {
  if (numFmt === undefined || numFmt === "General" || !isSafeNumberFormat(numFmt)) return undefined;
  try {
    return formatValue(value, numFmt);
  } catch {
    return undefined;
  }
}

/** A cell's display text: its number format when it has a usable one, else Excel's General rendering. */
function cellText(value: CellValue, numFmt: string | undefined, formatValue: FormatValue): string {
  if (value === null) return "";
  const formatted = formattedText(value, numFmt, formatValue);
  if (formatted !== undefined) return formatted;
  // 15 significant digits is Excel's precision: 0.1 + 0.2 shows as 0.3
  if (typeof value === "number") return String(Number(value.toPrecision(15)));
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (value instanceof Date) return isoDateText(value);
  return value;
}

/** Builds the string grid from A1 to the last non-empty cell, after checking that box against the limits. */
function textGrid(forEachCell: (visit: CellVisitor) => void, limits: GridLimits, formatValue: FormatValue): string[][] {
  let rowCount = 0;
  let columnCount = 0;
  forEachCell((row, col, value) => {
    if (value === null) return;
    if (row >= rowCount) rowCount = row + 1;
    if (col >= columnCount) columnCount = col + 1;
  });
  assertWithinLimits(rowCount, columnCount, limits);
  const grid = Array.from({ length: rowCount }, () => new Array<string>(columnCount).fill(""));
  forEachCell((row, col, value, numFmt) => {
    if (value !== null) grid[row]![col] = cellText(value, numFmt, formatValue);
  });
  return grid;
}

/** Maps hucre's limit errors to gridcn's messages; hucre has no error codes, so its message text is matched. */
function importError(err: unknown, hucre: HucreReader): unknown {
  if (err instanceof hucre.ZipError && err.message.includes("exceeds limit")) return new Error(PART_TOO_LARGE_MESSAGE, { cause: err });
  if (err instanceof hucre.ParseError) {
    if (/over the \d+ limit|more than \d+ filled cells/.test(err.message)) return new Error(IMPORT_TOO_MANY_CELLS_MESSAGE, { cause: err });
    if (err.message.startsWith("Unsupported XLS version")) return new Error(UNSUPPORTED_EXCEL_FORMAT_MESSAGE, { cause: err });
  }
  return err;
}

/** Reads the selected sheet of an xlsx workbook. Sparse mode keeps memory proportional to the real cells, whatever their box. */
async function readXlsxSheet(
  bytes: Uint8Array,
  sheetName: string | undefined,
  limits: ExcelLimits,
  { readXlsx, formatValue }: HucreReader,
): Promise<ParsedImportFile> {
  const sheetNames: string[] = [];
  const workbook = await readXlsx(bytes, {
    sheets: (info) => {
      sheetNames.push(info.name);
      return sheetName === undefined ? info.index === 0 : info.name === sheetName;
    },
    sparse: true,
    readStyles: true,
    maxDecompressedBytes: limits.maxDecompressedBytes,
  });
  if (sheetName !== undefined && !sheetNames.includes(sheetName)) throw new Error(`unknown sheet "${sheetName}"`);
  const sheet = workbook.sheets[0];
  if (!sheet) return { rows: [], sheetNames, sheetName };
  const rows = textGrid(
    (visit) => {
      for (const [key, cell] of sheet.cells ?? []) {
        const comma = key.indexOf(",");
        visit(Number(key.slice(0, comma)), Number(key.slice(comma + 1)), cell.value, cell.style?.numFmt);
      }
    },
    limits,
    formatValue,
  );
  return { rows, sheetNames, sheetName: sheet.name };
}

const OLE2_END_OF_CHAIN = 0xfffffffe;
const OLE2_FREE_SECTOR = 0xffffffff;
const OLE2_SECTOR_SHIFTS = [9, 12];
const OLE2_MINI_SECTOR_SHIFT = 6;
const OLE2_DEFAULT_MINI_CUTOFF = 4096;
const OLE2_DIRECTORY_ENTRY_BYTES = 128;
const UNREADABLE_XLS_MESSAGE = "unreadable-xls";

/** Records a workbook may hold besides its cells: formats, styles, fonts, sheet metadata. */
const XLS_RECORD_SLACK = 100_000;

/** The most records an xls workbook may hold: hucre keeps about 300 bytes per record, so half a record per cell of `maxCells` stays near 0.8 GB at the defaults. */
function maxXlsRecords(maxCells: number): number {
  return maxCells / 2 + XLS_RECORD_SLACK;
}

type Ole2Entry = { name: string; type: number; start: number; size: number };

const unreadableXls = () => new Error(UNREADABLE_XLS_MESSAGE);

/**
 * The `Workbook` (or `Book`) stream of an OLE2 container, read the way hucre's reader reads it. Fails closed
 * wherever hucre would take a path the scan cannot follow: duplicate stream names, chain loops, sizes past the data.
 */
function readOle2Workbook(bytes: Uint8Array): Uint8Array {
  if (bytes.length < 512) throw unreadableXls();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const sectorShift = view.getUint16(30, true);
  if (!OLE2_SECTOR_SHIFTS.includes(sectorShift) || view.getUint16(32, true) !== OLE2_MINI_SECTOR_SHIFT) throw unreadableXls();
  const sectorSize = 1 << sectorShift;
  const miniSectorSize = 1 << OLE2_MINI_SECTOR_SHIFT;
  const fatSectorCount = view.getUint32(44, true);
  const miniCutoff = view.getUint32(56, true) || OLE2_DEFAULT_MINI_CUTOFF;
  const miniFatSectorCount = view.getUint32(64, true);
  const difatSectorCount = view.getUint32(72, true);
  const maxSectors = Math.floor(bytes.length / sectorSize) + 1;
  const sectorAt = (sector: number) => {
    const at = (sector + 1) * sectorSize;
    if (at + sectorSize > bytes.length) throw unreadableXls();
    return at;
  };
  const fatSectors: number[] = [];
  for (let i = 0; i < 109 && fatSectors.length < fatSectorCount; i++) {
    const sector = view.getUint32(76 + i * 4, true);
    if (sector === OLE2_FREE_SECTOR || sector === OLE2_END_OF_CHAIN) break;
    fatSectors.push(sector);
  }
  const difatLimit = Math.min(difatSectorCount, maxSectors);
  let difat = view.getUint32(68, true);
  for (let hops = 0; difat !== OLE2_END_OF_CHAIN && difat !== OLE2_FREE_SECTOR && difatLimit > 0 && hops < difatLimit + 1; hops++) {
    const at = sectorAt(difat);
    for (let i = 0; i < sectorSize / 4 - 1 && fatSectors.length < fatSectorCount; i++) {
      const sector = view.getUint32(at + i * 4, true);
      if (sector !== OLE2_FREE_SECTOR && sector !== OLE2_END_OF_CHAIN) fatSectors.push(sector);
    }
    difat = view.getUint32(at + sectorSize - 4, true);
  }
  if (fatSectors.length > maxSectors || new Set(fatSectors).size !== fatSectors.length) throw unreadableXls();
  const fat = new Uint32Array((fatSectors.length * sectorSize) / 4);
  fatSectors.forEach((sector, index) => {
    const at = sectorAt(sector);
    for (let i = 0; i < sectorSize / 4; i++) fat[(index * sectorSize) / 4 + i] = view.getUint32(at + i * 4, true);
  });

  let hopsLeft = fat.length;
  const walk = (start: number): number[] => {
    const sectors: number[] = [];
    for (let sector = start; sector !== OLE2_END_OF_CHAIN && sector !== OLE2_FREE_SECTOR; sector = fat[sector] ?? OLE2_END_OF_CHAIN) {
      if (--hopsLeft < 0) throw unreadableXls();
      sectorAt(sector);
      sectors.push(sector);
    }
    return sectors;
  };
  const readChain = (start: number): Uint8Array => {
    const sectors = walk(start);
    const out = new Uint8Array(sectors.length * sectorSize);
    sectors.forEach((sector, index) => out.set(bytes.subarray(sectorAt(sector), sectorAt(sector) + sectorSize), index * sectorSize));
    return out;
  };

  const directory = readChain(view.getUint32(48, true));
  const directoryView = new DataView(directory.buffer);
  const entries: Ole2Entry[] = [];
  for (let at = 0; at + OLE2_DIRECTORY_ENTRY_BYTES <= directory.length; at += OLE2_DIRECTORY_ENTRY_BYTES) {
    const type = directory[at + 66]!;
    if (type === 0) continue;
    const nameLength = directoryView.getUint16(at + 64, true);
    let name = "";
    for (let i = 0; i + 1 < nameLength; i += 2) {
      const code = directoryView.getUint16(at + i, true);
      if (code === 0) break;
      name += String.fromCharCode(code);
    }
    entries.push({ name, type, start: directoryView.getUint32(at + 116, true), size: directoryView.getUint32(at + 120, true) });
  }
  const root = entries.find((entry) => entry.type === 5);
  if (!root) throw unreadableXls();
  const streams = entries.filter((entry) => entry.type === 2);
  const workbooks = streams.filter((entry) => entry.name === "Workbook");
  const books = streams.filter((entry) => entry.name === "Book");
  if (workbooks.length > 1 || books.length > 1) throw unreadableXls();
  const workbook = workbooks[0] ?? books[0];
  if (!workbook) throw unreadableXls();
  if (streams.reduce((total, entry) => total + entry.size, 0) > bytes.length) throw unreadableXls();

  const miniStream = readChain(root.start).subarray(0, root.size);
  const miniFatBytes =
    miniFatSectorCount > 0 && view.getUint32(60, true) !== OLE2_END_OF_CHAIN ? readChain(view.getUint32(60, true)).subarray(0, miniFatSectorCount * sectorSize) : new Uint8Array(0);
  const miniFatView = new DataView(miniFatBytes.buffer, miniFatBytes.byteOffset, miniFatBytes.byteLength);
  const miniFatLength = Math.floor(miniFatBytes.length / 4);
  let workbookBytes: Uint8Array = new Uint8Array(0);
  for (const stream of streams) {
    if (stream.size < miniCutoff) {
      if (stream.size > miniStream.length) throw unreadableXls();
      if (stream !== workbook) continue;
      workbookBytes = new Uint8Array(stream.size);
      let filled = 0;
      for (let sector = stream.start, hops = 0; filled < stream.size; sector = miniFatView.getUint32(sector * 4, true), hops++) {
        if (hops > miniFatLength || sector >= miniFatLength || (sector + 1) * miniSectorSize > miniStream.length) throw unreadableXls();
        const chunk = miniStream.subarray(sector * miniSectorSize, (sector + 1) * miniSectorSize);
        workbookBytes.set(chunk.subarray(0, stream.size - filled), filled);
        filled += chunk.length;
      }
    } else if (stream === workbook) {
      workbookBytes = readChain(stream.start).subarray(0, stream.size);
    } else {
      walk(stream.start);
    }
  }
  return workbookBytes;
}

const BIFF_BOF = 0x809;
const BIFF_EOF = 0x0a;
const BIFF_BOUNDSHEET = 0x85;
const BIFF8_VERSION = 0x600;
const BIFF_CELL_RECORDS = new Set([0xfd, 0x27e, 0x203, 0x205, 0x204, 0x06]);
const BIFF_MULRK = 0xbd;
const BIFF_MULRK_CELL_BYTES = 6;

type BiffRecord = { id: number; data: number; length: number };

/** Walks the BIFF records from `offset`, as hucre's `parseRecords` does; a record cut short by the stream end keeps the bytes that exist. */
function* biffRecords(stream: Uint8Array, view: DataView, offset: number): Generator<BiffRecord, void> {
  for (let at = offset; at + 4 <= stream.length; ) {
    const id = view.getUint16(at, true);
    const length = view.getUint16(at + 2, true);
    const data = at + 4;
    yield { id, data, length: Math.min(length, stream.length - data) };
    if (id === 0 && length === 0) return;
    at = data + length;
  }
}

/** How many records hucre's `parseRecords` would build, counted without building them; stops at `cap + 1`. */
function biffRecordCount(stream: Uint8Array, view: DataView, cap: number): number {
  let count = 0;
  for (let at = 0; at + 4 <= stream.length && count <= cap; count++) {
    const length = view.getUint16(at + 2, true);
    if (length === 0 && view.getUint16(at, true) === 0) return count + 1;
    at += 4 + length;
  }
  return count;
}

/** The cells a worksheet substream spans, and where its records end; reads on from the record after `start`, as hucre does, and stops once the span passes `cap`. */
function biffSheetBox(stream: Uint8Array, view: DataView, start: number, cap: number): { cells: number; end: number } {
  let rows = 0;
  let columns = 0;
  let end = start;
  let atStart = true;
  for (const { id, data, length } of biffRecords(stream, view, start)) {
    end = data + length;
    if (atStart) {
      atStart = false;
      continue;
    }
    if (id === BIFF_EOF) break;
    const mulrk = id === BIFF_MULRK;
    if (length < 4 || !(mulrk || BIFF_CELL_RECORDS.has(id))) continue;
    let lastColumn = view.getUint16(data + 2, true);
    if (mulrk) {
      if (length < 6) continue;
      const cells = (length - 6) / BIFF_MULRK_CELL_BYTES;
      if (!Number.isInteger(cells)) throw unreadableXls();
      if (cells === 0) continue;
      lastColumn += cells - 1;
    }
    rows = Math.max(rows, view.getUint16(data, true) + 1);
    columns = Math.max(columns, lastColumn + 1);
    if (rows * columns > cap) break;
  }
  return { cells: rows * columns, end };
}

// hucre pads every sheet and builds one object per record; bound both before it runs.
function assertXlsWithinLimits(bytes: Uint8Array, limits: GridLimits): void {
  const stream = readOle2Workbook(bytes);
  const view = new DataView(stream.buffer, stream.byteOffset, stream.byteLength);
  if (biffRecordCount(stream, view, maxXlsRecords(limits.maxCells)) > maxXlsRecords(limits.maxCells)) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  const sheetStarts: number[] = [];
  let atStart = true;
  for (const { id, data, length } of biffRecords(stream, view, 0)) {
    if (atStart) {
      if (id !== BIFF_BOF || (length >= 2 && view.getUint16(data, true) !== BIFF8_VERSION)) return;
      atStart = false;
      continue;
    }
    if (id === BIFF_EOF) break;
    if (id === BIFF_BOUNDSHEET && length >= 4) sheetStarts.push(view.getUint32(data, true));
  }
  const boxes = new Map<number, number>();
  let total = 0;
  let scanBudget = stream.length;
  for (const start of sheetStarts) {
    if (!boxes.has(start)) {
      const { cells, end } = biffSheetBox(stream, view, start, limits.maxCells);
      scanBudget -= end - start;
      if (scanBudget < 0) throw unreadableXls();
      boxes.set(start, cells);
    }
    total += boxes.get(start)!;
    if (total > limits.maxCells) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  }
}

/** Reads a BIFF8 `.xls` workbook; hucre parses every sheet, each bounded by `maxCells`, and returns values without number formats. */
async function readXlsSheet(
  bytes: Uint8Array,
  sheetName: string | undefined,
  limits: GridLimits,
  { readXls, formatValue }: HucreReader,
): Promise<ParsedImportFile> {
  assertXlsWithinLimits(bytes, limits);
  const workbook = await readXls(bytes, { maxTotalCells: limits.maxCells });
  const sheetNames = workbook.sheets.map((sheet) => sheet.name);
  const selected = sheetName !== undefined ? sheetNames.indexOf(sheetName) : 0;
  if (selected === -1) throw new Error(`unknown sheet "${sheetName}"`);
  const sheet = workbook.sheets[selected];
  if (!sheet) return { rows: [], sheetNames, sheetName };
  const rows = textGrid((visit) => sheet.rows.forEach((row, r) => row.forEach((value, c) => visit(r, c, value, undefined))), limits, formatValue);
  return { rows, sheetNames, sheetName: sheet.name };
}

/** Parses one sheet of an xlsx/xls workbook into a 2D string grid via lazily-imported hucre; `sheetName` selects the sheet (first by default). The file's signature, not its extension, picks the reader. */
async function parseExcelFile(file: File, sheetName: string | undefined, limits: ExcelLimits, signal?: AbortSignal): Promise<ParsedImportFile> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  if (signal?.aborted) throw abortError();
  const isXlsx = hasSignature(bytes, ZIP_SIGNATURE);
  if (!isXlsx && !hasSignature(bytes, OLE2_SIGNATURE)) throw new Error(UNSUPPORTED_EXCEL_FORMAT_MESSAGE);
  const parseLimits = isXlsx ? { ...limits, maxDecompressedBytes: partCap(limits) } : limits;
  if (isXlsx) assertEntriesWithin(bytes, parseLimits.maxDecompressedBytes);
  const hucre = await import("./xlsx-reader");
  try {
    return await (isXlsx ? readXlsxSheet : readXlsSheet)(bytes, sheetName, parseLimits, hucre);
  } catch (err) {
    throw importError(err, hucre);
  }
}

/**
 * Parses a `.csv`, `.tsv`, `.xlsx`, or `.xls` file into a normalized 2D string grid. CSV/TSV goes
 * through papaparse (delimiter auto-detect + override); Excel formats go through a
 * dynamically-imported hucre (it never loads for CSV-only consumers), the `sheetName` sheet
 * or the first one. `.xls` means Excel 97-2003 (BIFF8); other `.xls` flavours reject. `signal`
 * aborts the file read when set; an aborted parse rejects with an AbortError.
 */
export async function parseImportFile(file: File, options: ParseImportFileOptions = {}, signal?: AbortSignal): Promise<ParsedImportFile> {
  const maxFileBytes = options.maxFileBytes ?? DEFAULT_IMPORT_LIMITS.maxFileBytes;
  const limits: GridLimits = {
    maxRows: options.maxRows ?? DEFAULT_IMPORT_LIMITS.maxRows,
    maxColumns: options.maxColumns ?? DEFAULT_IMPORT_LIMITS.maxColumns,
    maxCells: options.maxCells ?? DEFAULT_IMPORT_LIMITS.maxCells,
  };
  // before any file read: file.size is synchronous, so the DoS check costs nothing
  if (file.size > maxFileBytes) throw new Error(FILE_TOO_LARGE_MESSAGE);
  if (isExcelFile(file)) {
    const maxDecompressedBytes = options.maxDecompressedBytes ?? DEFAULT_IMPORT_LIMITS.maxDecompressedBytes;
    return parseExcelFile(file, options.sheetName, { ...limits, maxDecompressedBytes }, signal);
  }
  if (isCsvFile(file)) {
    const text = await file.text();
    if (signal?.aborted) throw abortError();
    const parsed = parseCsvText(text, options.csvDelimiter, limits);
    let columns = 0;
    for (const row of parsed.rows) if (row.length > columns) columns = row.length;
    assertWithinLimits(parsed.rows.length, columns, limits);
    return parsed;
  }
  throw new Error("unsupported-file-type");
}

// A static re-export per direction lets bundlers tree-shake hucre's barrels inside the lazy chunk.
export { readXls, readXlsx } from "hucre/xlsx";
export { formatValue, ParseError, ZipError } from "hucre";

import type { CsvDelimiter } from "./parse-import-file";

/** Minimal column shape the header-matching/preview logic needs — matches `ColumnDef` structurally. */
export type ImportTargetColumn = { id: string; headerText?: string; header: unknown };

/**
 * Consumer-configurable defaults applied at PRESELECTION time only — the user can always
 * override any of these in the dialog once it's open. See import-export.mdx for the worked
 * example.
 */
export type ImportDefaults = {
  /** Skip auto-detect and preselect this delimiter. Detect still runs if undefined. */
  defaultDelimiter?: CsvDelimiter;
  /** false disables delimiter auto-detection; defaultDelimiter (or ",") is used. Default true. */
  autoDetectDelimiter?: boolean;
  /** Default for the header-row toggle. Default true (current behavior). */
  defaultHeaderRow?: boolean;
  /** Source columns to preselect as skipped: header names (case-insensitive) or indices. */
  defaultSkipColumns?: readonly (string | number)[];
  /**
   * Override the initial mapping per source column; return undefined to fall back to the
   * built-in matcher, null to skip. Wins over `defaultSkipColumns`.
   */
  mapColumn?: (header: string, index: number) => string | null | undefined;
};

/** Column display header for matching: `headerText`, else the string `header`, else the id. */
function columnMatchText(column: ImportTargetColumn): string {
  return column.headerText ?? (typeof column.header === "string" ? column.header : column.id);
}

/**
 * Prefills the import-column -> grid-column mapping by matching each imported header against
 * `column.headerText ?? header ?? column.id`, case-insensitively. Unmatched headers map to `null`
 * (the dialog's '—' skip option). Each grid column can only be claimed once — a later duplicate
 * match falls back to `null` (skip) since one-source-per-grid-column is enforced everywhere.
 */
export function matchImportColumns(importHeaders: readonly string[], gridColumns: readonly ImportTargetColumn[]): (string | null)[] {
  const byLowerText = new Map(gridColumns.map((column) => [columnMatchText(column).toLowerCase(), column.id] as const));
  const byLowerId = new Map(gridColumns.map((column) => [column.id.toLowerCase(), column.id] as const));

  const claimed = new Set<string>();
  return importHeaders.map((header) => {
    const key = header.trim().toLowerCase();
    const gridColumnId = byLowerText.get(key) ?? byLowerId.get(key) ?? null;
    if (gridColumnId === null || claimed.has(gridColumnId)) return null;
    claimed.add(gridColumnId);
    return gridColumnId;
  });
}

/** True when `defaultSkipColumns` names `header` (case-insensitive) or `index` (0-based). */
function isDefaultSkipped(header: string, index: number, defaultSkipColumns: readonly (string | number)[]): boolean {
  const key = header.trim().toLowerCase();
  return defaultSkipColumns.some((entry) => (typeof entry === "number" ? entry === index : entry.trim().toLowerCase() === key));
}

/**
 * Preselects the import-column -> grid-column mapping: starts from {@link matchImportColumns},
 * then applies `options.defaultSkipColumns` (by header name or index), then `options.mapColumn`
 * per column (wins over `defaultSkipColumns`; `undefined` keeps whatever came before it). All of
 * this only decides the dialog's *initial* mapping — the user can still change every cell by hand
 * once the dialog is open. Duplicate-claim dedup from {@link matchImportColumns} still applies
 * first; `mapColumn` overrides are trusted as-is and not deduped against each other, matching a
 * consumer's explicit intent.
 */
export function applyImportOptions(
  importHeaders: readonly string[],
  gridColumns: readonly ImportTargetColumn[],
  options: Pick<ImportDefaults, "defaultSkipColumns" | "mapColumn"> = {},
): (string | null)[] {
  const { defaultSkipColumns, mapColumn } = options;
  const matched = matchImportColumns(importHeaders, gridColumns);
  return matched.map((gridColumnId, index) => {
    const header = importHeaders[index] ?? "";
    const overridden = defaultSkipColumns && isDefaultSkipped(header, index, defaultSkipColumns) ? null : gridColumnId;
    const resolved = mapColumn?.(header, index);
    return resolved === undefined ? overridden : resolved;
  });
}

import type { AnyColumnDef, CellType, ColumnDef } from "@/registry/default/components/data-grid/data-grid";
import type { ValidateBatchItem, ValidateResult } from "@/registry/default/components/data-grid/data-grid-sdk";
import { isDev, resolveColumnValidate, runValidateBatch, setCellValue } from "@/registry/default/components/data-grid/data-grid-sdk";

/** One import-column -> grid-column mapping entry; `null` skips the import column. */
export type ImportColumnMapping = { importColumnIndex: number; gridColumnId: string | null };

/** Above this row count, `buildImportedRows` yields between chunks so the dialog stays responsive and Cancel can land. */
export const IMPORT_CHUNK_THRESHOLD_ROWS = 5_000;

/** Rows processed per chunk once {@link IMPORT_CHUNK_THRESHOLD_ROWS} is exceeded. */
const CHUNK_SIZE = 2_000;

/** One import cell whose value failed `column.validate`: the cell is cleared with its cell type's `clearValue()`, and the row is still imported. */
export type ImportRejectedCell = {
  /** 0-based index into `dataRows` (header row excluded). */
  rowIndex: number;
  /** 0-based index of the source column in the import file. */
  importColumnIndex: number;
  /** The grid column the value was mapped to and cleared in. */
  gridColumnId: string;
};

/** Result of {@link buildImportedRows}: the built rows plus every rejected (cleared) cell. */
export type BuildImportedRowsResult<TData> = {
  rows: TData[];
  /** Cells whose value failed `column.validate` and was cleared. Their rows are still built. */
  rejected: ImportRejectedCell[];
};

/** Inputs for {@link buildImportedRows}. */
export type BuildImportedRowsOptions<TData> = {
  /** Data rows only (header row, if any, already excluded by the caller). */
  dataRows: readonly string[][];
  mapping: readonly ImportColumnMapping[];
  // ColumnDef's 3rd param (TValidate) erases to `any`, not `unknown` — see data-grid/store.tsx's
  // AnyColumnDef doc: validate's function-or-schema union can't stay bivariant as a plain property.
  columns: readonly ColumnDef<TData, unknown, any>[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>;
  /** Builds a fresh row for import row `index`; required — the dialog never writes to the grid store directly. */
  createRow: (index: number) => TData;
  /** Checked between chunks on the large-import path; throws `"import-cancelled"` when true. Ignored below {@link IMPORT_CHUNK_THRESHOLD_ROWS}. */
  signal?: AbortSignal;
};

/** One import cell awaiting its validation verdict: where it goes, and what to write if the value is rejected. */
type ImportCell = {
  rowIndex: number;
  importColumnIndex: number;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- same TValidate erasure as BuildImportedRowsOptions.columns.
  column: ColumnDef<any, unknown, any>;
  clearedValue: unknown;
};

/** Thrown from the chunked path when `options.signal` is aborted between chunks. */
export const IMPORT_CANCELLED_MESSAGE = "import-cancelled";

/**
 * Builds `TData` rows from parsed import rows: one `createRow(index)` per row, then each mapped
 * cell is parsed through its column's cell type `fromText` and checked by `column.validate` —
 * invalid values are cleared via `clearValue()` rather than dropping the whole row, and every
 * rejected cell is listed in the result's `rejected`.
 *
 * Returns `{ rows, rejected }` directly when every validator is synchronous AND `dataRows` is at
 * or below {@link IMPORT_CHUNK_THRESHOLD_ROWS}. Above that row count, or when a column has an ASYNC
 * Standard Schema, this returns a Promise instead: large imports are built in chunks that yield to
 * the event loop (so the dialog repaints and `options.signal` can cancel between chunks), and any
 * async validators run with the shared chunked concurrency cap. The import dialog's existing
 * pending affordance covers both waits.
 *
 * The function form's second argument is the row as `createRow` returned it, not the row with this
 * import row's earlier columns already folded in — validating a whole import row concurrently and
 * validating it left to right cannot both be true, and the fresh row is the predictable one.
 */
export function buildImportedRows<TData>(options: BuildImportedRowsOptions<TData>): BuildImportedRowsResult<TData> | Promise<BuildImportedRowsResult<TData>> {
  const { dataRows, mapping, columns, cellTypes, createRow, signal } = options;
  const columnsById = new Map(columns.map((column) => [column.id, column] as const));
  const activeMappings = mapping.filter((m): m is { importColumnIndex: number; gridColumnId: string } => m.gridColumnId !== null);

  // the dialog UI prevents duplicate mappings, a custom UI's setMapping does not — the later
  // mapping wins silently, so make it visible in dev (one warn per duplicated column)
  const seenColumns = new Set<string>();
  const warnedColumns = new Set<string>();
  for (const { gridColumnId } of activeMappings) {
    if (seenColumns.has(gridColumnId) && !warnedColumns.has(gridColumnId)) {
      warnedColumns.add(gridColumnId);
      if (isDev()) console.warn(`[data-grid-io] buildImportedRows: grid column "${gridColumnId}" is mapped by more than one import column - the later mapping wins`);
    }
    seenColumns.add(gridColumnId);
  }

  if (dataRows.length > IMPORT_CHUNK_THRESHOLD_ROWS) {
    return buildImportedRowsChunked(dataRows, activeMappings, columnsById, cellTypes, createRow, signal);
  }

  const rows = dataRows.map((_, index) => createRow(index));
  const rejected: ImportRejectedCell[] = [];
  const { items, cells } = buildCellsForRange(dataRows, 0, dataRows.length, activeMappings, columnsById, cellTypes, rows);

  const results = runValidateBatch(items);
  if (results instanceof Promise) return results.then((resolved) => ({ rows: writeCells(rows, cells, resolved, rejected), rejected }));
  return { rows: writeCells(rows, cells, results, rejected), rejected };
}

/** One resolved mapping entry: the source column index paired with its target column definition. */
type ResolvedMapping = { importColumnIndex: number; gridColumnId: string };

/** Builds `rows[start, end)`'s validation items/cells against the already-created `rows` array. */
function buildCellsForRange<TData>(
  dataRows: readonly string[][],
  start: number,
  end: number,
  activeMappings: readonly ResolvedMapping[],
  columnsById: ReadonlyMap<string, ColumnDef<TData, unknown, any>>, // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>,
  rows: TData[],
): { items: ValidateBatchItem[]; cells: ImportCell[] } {
  const items: ValidateBatchItem[] = [];
  const cells: ImportCell[] = [];
  for (let rowIndex = start; rowIndex < end; rowIndex++) {
    const sourceRow = dataRows[rowIndex]!; // start/end are within dataRows.length by construction
    for (const { importColumnIndex, gridColumnId } of activeMappings) {
      const column = columnsById.get(gridColumnId);
      if (!column) continue;
      const cellType = cellTypes[column.type ?? "text"];
      if (!cellType) continue;

      const text = sourceRow[importColumnIndex] ?? "";
      // as never: validate is typed against this column's own TData/TValue, which TS can't unify with the generic TData/unknown here — safe since column and row/value are all this same import's TData.
      items.push({ validate: resolveColumnValidate(column as AnyColumnDef, cellType) as never, value: cellType.fromText(text, column.options), row: rows[rowIndex] });
      cells.push({ rowIndex, importColumnIndex, column, clearedValue: cellType.clearValue(column.options) });
    }
  }
  return { items, cells };
}

/** Yields to the event loop; a chunk boundary for both the main-thread-block fix and the Cancel affordance. */
function yieldToEventLoop(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve));
}

/**
 * Large-import path: builds and writes rows {@link CHUNK_SIZE} at a time, yielding between chunks so
 * the dialog's pending state actually repaints and `signal` gets a chance to cancel. Validation still
 * runs once per chunk (not once for the whole import) so a huge async-schema import doesn't hold
 * `CHUNK_SIZE`-multiples of items in flight at once.
 */
async function buildImportedRowsChunked<TData>(
  dataRows: readonly string[][],
  activeMappings: readonly ResolvedMapping[],
  columnsById: ReadonlyMap<string, ColumnDef<TData, unknown, any>>, // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>,
  createRow: (index: number) => TData,
  signal?: AbortSignal,
): Promise<BuildImportedRowsResult<TData>> {
  const rows = dataRows.map((_, index) => createRow(index));
  const rejected: ImportRejectedCell[] = [];

  for (let start = 0; start < dataRows.length; start += CHUNK_SIZE) {
    if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
    const end = Math.min(start + CHUNK_SIZE, dataRows.length);
    const { items, cells } = buildCellsForRange(dataRows, start, end, activeMappings, columnsById, cellTypes, rows);
    const results = await runValidateBatch(items);
    writeCells(rows, cells, results, rejected);
    await yieldToEventLoop();
  }
  if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);

  return { rows, rejected };
}

/**
 * Folds each verdict into its row: the validator's output on success, the cell type's `clearValue()`
 * on rejection (the rejected cell is appended to `rejected`). `cells` is grouped by `rowIndex`
 * (built in mapping order per row), so a run of
 * consecutive plain-`accessorKey` cells for the same row is merged into one spread instead of one
 * spread per cell — this was the measured hot spot, one spread + 2 temp objects per cell at scale.
 * The run is flushed (a) before a `setValue` cell in the same row, so `setValue` still sees every
 * earlier cell's write, exactly as the un-merged left-to-right spreads did, and (b) at each row
 * boundary. A column with a custom `setValue` keeps writing through `setCellValue` per cell, since
 * only `setValue` knows how to fold its own value into the row.
 */
function writeCells<TData>(rows: TData[], cells: readonly ImportCell[], results: readonly ValidateResult[], rejected: ImportRejectedCell[]): TData[] {
  let pendingRow = -1;
  let pendingPatch: Record<string, unknown> | null = null;
  const flush = () => {
    if (pendingPatch === null) return;
    // as TData: TData is generic here, but pendingPatch's keys are this same TData's own accessorKeys — mirrors setCellValue's own accessorKey-spread branch.
    rows[pendingRow] = { ...rows[pendingRow], ...pendingPatch } as TData;
    pendingPatch = null;
  };

  for (let i = 0; i < cells.length; i++) {
    const cell = cells[i]!; // i < cells.length by loop condition
    const result = results[i];
    if (!result) continue;
    const isRejected = "error" in result;
    if (isRejected) rejected.push({ rowIndex: cell.rowIndex, importColumnIndex: cell.importColumnIndex, gridColumnId: cell.column.id });
    const value = isRejected ? cell.clearedValue : result.value;

    if (cell.rowIndex !== pendingRow) flush();
    pendingRow = cell.rowIndex;

    if (!cell.column.setValue && cell.column.accessorKey) {
      pendingPatch ??= {};
      pendingPatch[cell.column.accessorKey] = value;
      continue;
    }
    flush();
    // as never: setCellValue is typed against this column's own TData/TValue, which TS can't unify with the generic TData/unknown here — safe since column and row/value are all this same import's TData.
    rows[cell.rowIndex] = setCellValue(rows[cell.rowIndex] as never, cell.column as never, value as never) as TData;
  }
  flush();
  return rows;
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import { FILE_TOO_LARGE_MESSAGE, IMPORT_TOO_MANY_CELLS_MESSAGE, PART_TOO_LARGE_MESSAGE, UNSUPPORTED_EXCEL_FORMAT_MESSAGE, parseImportFile, type CsvDelimiter, type ImportLimits } from "./parse-import-file";
import { applyImportOptions, type ImportTargetColumn, type ImportDefaults } from "./match-import-column";
import type { ImportColumnMapping } from "./build-imported-rows";

export type { ImportTargetColumn, ImportDefaults };

/** Rows shown in the preview table, capped for readability. */
export const IMPORT_PREVIEW_ROW_COUNT = 10;

/** Keys into `labels.io` for the parse-failure messages {@link useDataGridImportPreview} can surface. */
export type ImportErrorKey = "errorParseFailed" | "errorNoRows" | "errorUnsupportedFile" | "errorUnsupportedExcelFormat" | "errorFileTooLarge" | "errorPartTooLarge" | "errorTooManyCells";

/** Error thrown by {@link parseImportFile} for extensions outside csv/xlsx/xls. */
const UNSUPPORTED_FILE_TYPE_MESSAGE = "unsupported-file-type";

/** True when a parse was aborted (new file chosen, dialog closed) — the caller drops the result instead of surfacing an error. */
function isAbortError(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

/** Maps a parse failure to its dialog error key; null for aborts the caller drops silently. */
function importErrorKey(err: unknown): ImportErrorKey | null {
  if (isAbortError(err)) return null;
  if (err instanceof Error) {
    switch (err.message) {
      case UNSUPPORTED_FILE_TYPE_MESSAGE:
        return "errorUnsupportedFile";
      case UNSUPPORTED_EXCEL_FORMAT_MESSAGE:
        return "errorUnsupportedExcelFormat";
      case FILE_TOO_LARGE_MESSAGE:
        return "errorFileTooLarge";
      case PART_TOO_LARGE_MESSAGE:
        return "errorPartTooLarge";
      case IMPORT_TOO_MANY_CELLS_MESSAGE:
        return "errorTooManyCells";
    }
  }
  return "errorParseFailed";
}

/** Parsed-and-ready import state, once a file has been chosen and parsed successfully. */
export type ImportFileState = {
  fileName: string;
  /** All parsed rows, including the header row (if `hasHeaderRow`) at index 0. */
  rows: string[][];
  hasHeaderRow: boolean;
  /** Display header per column: the file's header row text, or `labels.io.columnFallback(N)` when there's no header row. */
  importHeaders: string[];
  mapping: ImportColumnMapping[];
  delimiter?: CsvDelimiter;
  /** Every sheet name in the workbook. Undefined for CSV. Lets a consumer offer a sheet picker when a workbook has more than one sheet. */
  sheetNames?: string[];
  /** The sheet `rows` came from (first by default, or the one selected via {@link UseDataGridImportPreviewResult.setSheetName}). Undefined for CSV. */
  sheetName?: string;
};

/** Return value of {@link useDataGridImportPreview}. */
export type UseDataGridImportPreviewResult = {
  preview: ImportFileState | null;
  error: ImportErrorKey | null;
  /** True while a file is being read/parsed. */
  isParsing: boolean;
  /** Parses `file`; on success populates `preview` with column mapping prefilled by header-text match. */
  loadFile: (file: File, gridColumns: readonly ImportTargetColumn[]) => Promise<void>;
  setHasHeaderRow: (hasHeaderRow: boolean) => void;
  /** Re-parses the current CSV file with the given delimiter override; no-op for xlsx/xls files or before a file is loaded. A failed re-parse sets `error` instead of throwing. */
  setDelimiter: (delimiter: CsvDelimiter) => Promise<void>;
  /**
   * Re-parses the current xlsx/xls workbook with the given sheet; no-op for CSV or before a file
   * is loaded. Switching sheets recomputes the column mapping from scratch (different headers), so
   * any manual mapping the user set on the previous sheet is discarded.
   */
  setSheetName: (sheetName: string) => Promise<void>;
  setMapping: (importColumnIndex: number, gridColumnId: string | null) => void;
  reset: () => void;
  /** Data rows only (header row excluded when `hasHeaderRow`), capped to `IMPORT_PREVIEW_ROW_COUNT` for the preview table. */
  previewRows: string[][];
  /** All data rows (header row excluded when `hasHeaderRow`) — the full set `onImport` will build from. */
  importRows: string[][];
};

/** Builds display headers: the file's header row when present, else `labels.io.columnFallback(N)`. */
function computeImportHeaders(rows: string[][], hasHeaderRow: boolean, columnFallback: (index: number) => string): string[] {
  const columnCount = rows[0]?.length ?? 0;
  if (hasHeaderRow && rows[0]) return rows[0];
  return Array.from({ length: columnCount }, (_, i) => columnFallback(i + 1));
}

/** Resolves the `csvDelimiter` override to parse with, given `ImportDefaults`; undefined means "let auto-detect run". */
function resolveDelimiterOverride(options: ImportDefaults): CsvDelimiter | undefined {
  if (options.autoDetectDelimiter === false) return options.defaultDelimiter ?? ",";
  return options.defaultDelimiter;
}

/** Options for {@link useDataGridImportPreview}. */
export type UseDataGridImportPreviewOptions = {
  /** `labels.io.columnFallback` — builds the header shown for column N when the file has no header row. */
  columnFallback: (index: number) => string;
  /** Preselection defaults (see {@link ImportDefaults}). */
  defaults?: ImportDefaults;
  /** Size, row, column, cell, and unpacked-size bounds for every parse; omitted fields use `DEFAULT_IMPORT_LIMITS`. */
  limits?: ImportLimits;
};

/**
 * Owns the parse -> preview -> column-mapping state for the import dialog. File I/O and header
 * matching are pure functions ({@link parseImportFile}, {@link applyImportOptions}); this hook only
 * sequences them and exposes editable dialog state (header-row toggle, delimiter, per-column mapping).
 *
 */
export function useDataGridImportPreview(options: UseDataGridImportPreviewOptions): UseDataGridImportPreviewResult {
  const { columnFallback, defaults = {}, limits = {} } = options;
  const [preview, setPreview] = useState<ImportFileState | null>(null);
  const [error, setError] = useState<ImportErrorKey | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  // kept for delimiter-override re-parses, which need the original file + target columns again.
  const currentFileRef = useRef<File | null>(null);
  const gridColumnsRef = useRef<readonly ImportTargetColumn[]>([]);
  // aborts an in-flight file read when a newer load starts or the dialog resets.
  const parseControllerRef = useRef<AbortController | null>(null);
  // generation guard for every async parse (file load, sheet switch, delimiter override): a newer parse or reset wins over a slower older one.
  const parseGenerationRef = useRef(0);
  const { defaultHeaderRow = true, defaultSkipColumns, mapColumn } = defaults;
  const { maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes } = limits;
  const limitOptions = useMemo(
    () => ({ maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes }),
    [maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes],
  );

  const reset = useCallback(() => {
    parseGenerationRef.current += 1;
    parseControllerRef.current?.abort();
    setPreview(null);
    setError(null);
    setIsParsing(false);
    currentFileRef.current = null;
    gridColumnsRef.current = [];
  }, []);

  const loadFile = useCallback(async (file: File, gridColumns: readonly ImportTargetColumn[]) => {
    const generation = ++parseGenerationRef.current;
    // a re-parse started while this file loads has no file to re-parse, so it cannot outlive this load
    currentFileRef.current = null;
    parseControllerRef.current?.abort();
    const controller = new AbortController();
    parseControllerRef.current = controller;
    setError(null);
    setIsParsing(true);
    try {
      const parsed = await parseImportFile(file, { ...limitOptions, csvDelimiter: resolveDelimiterOverride(defaults) }, controller.signal);
      if (generation !== parseGenerationRef.current) return; // superseded by a newer file load or a reset
      if (parsed.rows.length === 0) {
        setError("errorNoRows");
        setPreview(null);
        return;
      }
      currentFileRef.current = file;
      gridColumnsRef.current = gridColumns;
      const hasHeaderRow = defaultHeaderRow;
      const importHeaders = computeImportHeaders(parsed.rows, hasHeaderRow, columnFallback);
      const matched = applyImportOptions(importHeaders, gridColumns, { defaultSkipColumns, mapColumn });
      setPreview({
        fileName: file.name,
        rows: parsed.rows,
        hasHeaderRow,
        importHeaders,
        mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
        delimiter: parsed.delimiter,
        sheetNames: parsed.sheetNames,
        sheetName: parsed.sheetName,
      });
    } catch (err) {
      const key = importErrorKey(err);
      if (key === null || generation !== parseGenerationRef.current) return; // superseded by a newer file or a dialog reset
      setError(key);
      setPreview(null);
    } finally {
      // a superseded (aborted) load must not clear the newer load's parsing state
      if (parseControllerRef.current === controller) setIsParsing(false);
    }
    // oxlint-disable-next-line react-hooks/exhaustive-deps -- destructured option fields are the real deps; `defaults` itself may be a fresh object each render.
  }, [columnFallback, defaultHeaderRow, defaultSkipColumns, mapColumn, limitOptions]);

  const setHasHeaderRow = useCallback(
    (hasHeaderRow: boolean) => {
      setPreview((prev) => {
        if (!prev) return prev;
        const importHeaders = computeImportHeaders(prev.rows, hasHeaderRow, columnFallback);
        return { ...prev, hasHeaderRow, importHeaders };
      });
    },
    [columnFallback],
  );

  const setDelimiter = useCallback(
    async (delimiter: CsvDelimiter) => {
      const file = currentFileRef.current;
      if (!file) return;
      const generation = ++parseGenerationRef.current;
      setError(null);
      setIsParsing(true);
      try {
        const parsed = await parseImportFile(file, { ...limitOptions, csvDelimiter: delimiter }, parseControllerRef.current?.signal);
        if (generation !== parseGenerationRef.current) return; // superseded by a newer file load, sheet switch, or reset
        if (parsed.rows.length === 0) return;
        setPreview((prev) => {
          if (!prev) return prev;
          const importHeaders = computeImportHeaders(parsed.rows, prev.hasHeaderRow, columnFallback);
          const matched = applyImportOptions(importHeaders, gridColumnsRef.current, { defaultSkipColumns, mapColumn });
          return {
            ...prev,
            rows: parsed.rows,
            importHeaders,
            delimiter,
            mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
          };
        });
      } catch (err) {
        const key = importErrorKey(err);
        if (key === null) return;
        if (generation === parseGenerationRef.current) setError(key);
      } finally {
        if (generation === parseGenerationRef.current) setIsParsing(false);
      }
    },
    [columnFallback, defaultSkipColumns, mapColumn, limitOptions],
  );

  const setSheetName = useCallback(
    async (sheetName: string) => {
      const file = currentFileRef.current;
      if (!file) return;
      const generation = ++parseGenerationRef.current;
      setError(null);
      setIsParsing(true);
      try {
        const parsed = await parseImportFile(file, { ...limitOptions, sheetName }, parseControllerRef.current?.signal);
        if (generation !== parseGenerationRef.current) return; // superseded by a newer sheet switch, file load, or reset
        if (parsed.rows.length === 0) {
          // empty sheet: the picker keeps the chosen name honest, the preview clears, Import stays disabled
          setPreview((prev) =>
            prev ? { ...prev, rows: [], importHeaders: [], mapping: [], sheetName: parsed.sheetName ?? sheetName } : prev,
          );
          setError("errorNoRows");
          return;
        }
        setPreview((prev) => {
          if (!prev) return prev;
          const importHeaders = computeImportHeaders(parsed.rows, prev.hasHeaderRow, columnFallback);
          const matched = applyImportOptions(importHeaders, gridColumnsRef.current, { defaultSkipColumns, mapColumn });
          return {
            ...prev,
            rows: parsed.rows,
            importHeaders,
            sheetName: parsed.sheetName,
            mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
          };
        });
      } catch (err) {
        const key = importErrorKey(err);
        if (key === null) return;
        if (generation === parseGenerationRef.current) setError(key);
      } finally {
        if (generation === parseGenerationRef.current) setIsParsing(false);
      }
    },
    [columnFallback, defaultSkipColumns, mapColumn, limitOptions],
  );

  const setMapping = useCallback((importColumnIndex: number, gridColumnId: string | null) => {
    setPreview((prev) => {
      if (!prev) return prev;
      const mapping = prev.mapping.map((m) => (m.importColumnIndex === importColumnIndex ? { ...m, gridColumnId } : m));
      return { ...prev, mapping };
    });
  }, []);

  const importRows = useMemo(() => {
    if (!preview) return [];
    return preview.hasHeaderRow ? preview.rows.slice(1) : preview.rows;
  }, [preview]);

  const previewRows = useMemo(() => importRows.slice(0, IMPORT_PREVIEW_ROW_COUNT), [importRows]);

  return { preview, error, isParsing, loadFile, setHasHeaderRow, setDelimiter, setSheetName, setMapping, reset, previewRows, importRows };
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from "react";
import { Paperclip, X } from "lucide-react";
import { useDataGridActions, useDataGridAllColumns, useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, isDev, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { buildImportedRows, type ImportRejectedCell } from "./build-imported-rows";
import { useDataGridImportPreview, type ImportTargetColumn, type ImportDefaults } from "./use-data-grid-import";
import { DEFAULT_IMPORT_LIMITS, type CsvDelimiter, type ImportLimits } from "./parse-import-file";
import { Dropzone, DropzoneEmptyState, type DropzoneAccept, type DropzoneRejection } from "@/registry/default/components/dropzone/dropzone";

/** Accepted import file types, shared by the file input and the {@link Dropzone}. */
const IMPORT_ACCEPT: DropzoneAccept = {
  "text/csv": [".csv"],
  "text/tab-separated-values": [".tsv"],
  "application/vnd.ms-excel": [".xls"],
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": [".xlsx"],
};

export type { ImportDefaults };

const DELIMITER_OPTIONS: { value: CsvDelimiter; labelKey: "delimiterComma" | "delimiterSemicolon" | "delimiterTab" }[] = [
  { value: ",", labelKey: "delimiterComma" },
  { value: ";", labelKey: "delimiterSemicolon" },
  { value: "\t", labelKey: "delimiterTab" },
];

/** Mapping-select value for a source column that maps to no grid column. */
const SKIP_VALUE = "__skip__";

/** Props for {@link DataGridImportDialog}. */
export type DataGridImportDialogProps<TData> = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Builds a fresh row for import row `index`; required — the dialog never writes to the grid store directly. */
  createRow: (index: number) => TData;
  /** Called with the fully-built rows on confirm; the consumer decides how to merge (replace/append). Cells rejected by `validate` are already cleared in these rows. May be async (e.g. a server upsert) — the dialog stays pending until it settles and surfaces a rejection instead of closing. */
  onImport: (rows: TData[]) => void | Promise<void>;
  /** Consumer-configurable preselection defaults (delimiter, header row, skip columns, mapping). Omit for today's behavior unchanged. */
  importDefaults?: ImportDefaults;
  /** Size, row, column, cell, and unpacked-size bounds for the file; omitted fields use `DEFAULT_IMPORT_LIMITS`. `maxFileBytes` also sets the drop zone's `maxSize`. */
  importLimits?: ImportLimits;
};

/**
 * File-picker -> preview -> column-mapping -> confirm dialog. Parses via
 * {@link useDataGridImportPreview}, builds `TData` rows via {@link buildImportedRows} through each mapped
 * column's cell-type `fromText` + `validate`, then hands the rows to `onImport` — it never writes
 * to the grid store directly, so replace/append semantics stay the consumer's call. A cell that
 * fails `validate` is cleared (via its cell type's `clearValue()`), not dropped as a row; the
 * rejected cells are listed in {@link buildImportedRows}'s `rejected` result.
 */
export function DataGridImportDialog<TData>(props: DataGridImportDialogProps<TData>): ReactNode {
  const { open, onOpenChange, createRow, onImport, importDefaults, importLimits } = props;
  const maxFileBytes = importLimits?.maxFileBytes ?? DEFAULT_IMPORT_LIMITS.maxFileBytes;
  const labels = useDataGridLabels();
  const actions = useDataGridActions();
  const storeApi = useDataGridStoreApi();
  const allColumns = useDataGridAllColumns<TData>();
  const [isValidating, setIsValidating] = useState(false);
  /** Generation guard for a held async import: a newer confirm, or closing the dialog, drops the older batch. */
  const confirmTokenRef = useRef(0);
  /** Aborts the in-flight chunked build (large sync imports and async-schema imports alike) when Cancel is clicked or the dialog closes. */
  const abortControllerRef = useRef<AbortController | null>(null);
  const headerRowId = useId();
  const { preview, error, isParsing, loadFile, setHasHeaderRow, setDelimiter, setSheetName, setMapping, reset, previewRows, importRows } =
    useDataGridImportPreview({ columnFallback: labels.io.columnFallback, defaults: importDefaults, limits: importLimits });
  // Base UI's SelectValue shows the raw value until the popup mounts its items, unless the root gets `items`
  const delimiterItems = DELIMITER_OPTIONS.map((option) => ({ value: option.value, label: labels.io[option.labelKey] }));
  const mappingItems = [{ value: SKIP_VALUE, label: labels.io.skipColumn }, ...allColumns.map((column) => ({ value: column.id, label: columnLabelText(column) }))];

  useEffect(() => {
    if (open) return;
    confirmTokenRef.current += 1;
    abortControllerRef.current?.abort();
    setIsValidating(false);
    setRejectedCount(0);
    setMergeFailed(false);
    reset();
  }, [open, reset]);

  const onFile = useCallback(
    (file: File) => {
      const targets: ImportTargetColumn[] = allColumns.map((c) => ({ id: c.id, headerText: c.headerText, header: c.header }));
      setRejectedCount(0);
      setMergeFailed(false);
      void loadFile(file, targets);
    },
    [allColumns, loadFile],
  );

  const onDropFiles = useCallback(
    (acceptedFiles: File[], rejections: DropzoneRejection[]) => {
      // a maxSize rejection is re-routed through loadFile so the parse's own size check surfaces the dialog's too-large error
      const file = acceptedFiles[0] ?? (rejections.some((r) => r.reasons.includes("maxSize")) ? rejections[0]?.file : undefined);
      if (file) onFile(file);
    },
    [onFile],
  );

  /** Rejected-cell count from the last confirmed build; non-zero keeps the dialog open so the warning is visible. */
  const [rejectedCount, setRejectedCount] = useState(0);
  /** True when `onImport` rejected; the dialog stays open and the import can be retried. */
  const [mergeFailed, setMergeFailed] = useState(false);
  const finish = useCallback(
    (rows: TData[], rejected: readonly ImportRejectedCell[]) => {
      setMergeFailed(false);
      setIsValidating(true);
      void Promise.resolve()
        .then(() => onImport(rows))
        .then(() => {
          actions.clearSelection();
        })
        .then(
          () => {
            setIsValidating(false);
            if (rejected.length > 0) {
              setRejectedCount(rejected.length);
              return;
            }
            onOpenChange(false);
          },
          (error) => {
            setIsValidating(false);
            setMergeFailed(true);
            if (isDev()) console.warn("[data-grid-io] onImport rejected; the dialog stays open", error);
          },
        );
    },
    [onImport, actions, onOpenChange],
  );

  const onConfirm = useCallback(() => {
    if (!preview) return;
    const state = storeApi.getState();
    const abortController = new AbortController();
    abortControllerRef.current = abortController;
    // state.cellTypes comes back from the generic-erased store (TData = unknown, see core store.tsx's InternalSyncProps comment); re-widened here to this dialog's own TData. allColumns is already TData-typed via useDataGridAllColumns<TData>() above.
    const built = buildImportedRows<TData>({
      dataRows: importRows,
      mapping: preview.mapping,
      columns: allColumns,
      cellTypes: state.cellTypes as never,
      createRow,
      signal: abortController.signal,
    });
    if (!(built instanceof Promise)) {
      finish(built.rows, built.rejected);
      return;
    }
    // A large import (chunked so the dialog can repaint and Cancel can land) or an async schema on a
    // mapped column: the dialog stays open with Import disabled — the existing pending affordance —
    // and closes when the last verdict is in, or drops the batch silently if Cancel/close beat it.
    const token = ++confirmTokenRef.current;
    setIsValidating(true);
    void built.then(
      (result) => {
        if (confirmTokenRef.current !== token) return; // superseded by a newer confirm, or the dialog reset
        setIsValidating(false);
        finish(result.rows, result.rejected);
      },
      () => {
        // cancelled (signal aborted) or a validator threw outside runValidateBatch's own guard — either way, no rows to import.
        if (confirmTokenRef.current !== token) return;
        setIsValidating(false);
      },
    );
  }, [preview, importRows, allColumns, storeApi, createRow, finish]);

  const onCancel = useCallback(() => {
    abortControllerRef.current?.abort();
    onOpenChange(false);
  }, [onOpenChange]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[80vh] min-w-0 overflow-y-auto sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{labels.io.importDialogTitle}</DialogTitle>
          <DialogDescription>{labels.io.importDialogDescription}</DialogDescription>
        </DialogHeader>

        <div className="flex min-w-0 flex-col gap-3">
          {preview ? (
            <Dropzone compact accept={IMPORT_ACCEPT} maxFiles={1} maxSize={maxFileBytes} onDrop={onDropFiles} aria-label={labels.io.chooseFile}>
              <Paperclip className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
              <span className="min-w-0 flex-1 truncate text-sm text-foreground">{preview.fileName}</span>
              <span className="shrink-0 text-xs text-muted-foreground">{labels.io.replaceFile}</span>
            </Dropzone>
          ) : (
            <Dropzone accept={IMPORT_ACCEPT} maxFiles={1} maxSize={maxFileBytes} onDrop={onDropFiles} aria-label={labels.io.chooseFile}>
              <DropzoneEmptyState title={labels.io.chooseFile} description={`${labels.io.noFileChosen} — ${labels.io.maxFileSize(maxFileBytes)}`} />
            </Dropzone>
          )}

          {error && <p role="alert" className="text-sm text-destructive">{labels.io[error]}</p>}

          {rejectedCount > 0 && <p role="alert" className="text-sm text-destructive">{labels.io.importRejectedCells(rejectedCount)}</p>}

          {mergeFailed && <p role="alert" className="text-sm text-destructive">{labels.io.importMergeFailed}</p>}

          {preview && (
            <>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <Checkbox id={headerRowId} checked={preview.hasHeaderRow} onCheckedChange={(checked) => setHasHeaderRow(checked === true)} />
                  <Label htmlFor={headerRowId}>{labels.io.hasHeaderRow}</Label>
                </div>
                {preview.delimiter !== undefined && (
                  <label className="flex items-center gap-2 text-sm text-foreground">
                    {labels.io.delimiter}
                    <Select items={delimiterItems} value={preview.delimiter} onValueChange={(value) => void setDelimiter(value as CsvDelimiter)}>
                      <SelectTrigger className="w-36" size="sm" aria-label={labels.io.delimiter}>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {delimiterItems.map((item) => (
                          <SelectItem key={item.value} value={item.value}>
                            {item.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </label>
                )}
                {preview.sheetNames !== undefined && preview.sheetNames.length > 1 && (
                  <label className="flex items-center gap-2 text-sm text-foreground">
                    {labels.io.sheet}
                    <Select value={preview.sheetName ?? preview.sheetNames[0]} onValueChange={(value) => void setSheetName(value as string)}>
                      <SelectTrigger className="w-40" size="sm" aria-label={labels.io.sheet}>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {preview.sheetNames.map((name) => (
                          <SelectItem key={name} value={name} title={name}>
                            {name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </label>
                )}
              </div>

              <div className="flex min-w-0 flex-col gap-1">
                <span className="text-sm font-medium text-foreground">{labels.io.mapColumns}</span>
                <div className="min-w-0 overflow-hidden rounded-md border border-border">
                  {/* fixed layout gives every column an identical track — keeps selects and preview cells aligned */}
                  <Table className="table-fixed" style={{ minWidth: `${preview.importHeaders.length * 9}rem` }}>
                    <TableHeader>
                      <TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent">
                        {preview.importHeaders.map((header, importColumnIndex) => {
                          const currentGridColumnId = preview.mapping[importColumnIndex]?.gridColumnId ?? null;
                          // one source per grid column: a column mapped elsewhere is disabled
                          const takenElsewhere = new Set(
                            preview.mapping
                              .filter((m) => m.importColumnIndex !== importColumnIndex && m.gridColumnId !== null)
                              .map((m) => m.gridColumnId),
                          );
                          return (
                            <TableHead key={importColumnIndex} className="h-auto bg-muted/50 p-1.5 align-top whitespace-normal">
                              <div className="mb-1 truncate" title={header}>
                                {header}
                              </div>
                              <div className="flex items-center gap-1">
                                <Select
                                  items={mappingItems}
                                  value={currentGridColumnId ?? SKIP_VALUE}
                                  onValueChange={(value) =>
                                    setMapping(importColumnIndex, value === SKIP_VALUE || value === null ? null : value)
                                  }
                                >
                                  <SelectTrigger className="w-full" size="sm" aria-label={labels.io.mapColumnAriaLabel(header)}>
                                    <SelectValue />
                                  </SelectTrigger>
                                  <SelectContent>
                                    {mappingItems.map((item) => (
                                      <SelectItem key={item.value} value={item.value} disabled={takenElsewhere.has(item.value)}>
                                        {item.label}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                                {currentGridColumnId !== null && (
                                  <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    className="size-7 shrink-0"
                                    aria-label={labels.io.skipColumnQuick}
                                    onClick={() => setMapping(importColumnIndex, null)}
                                  >
                                    <X className="size-3.5" />
                                  </Button>
                                )}
                              </div>
                            </TableHead>
                          );
                        })}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {previewRows.map((row, rowIndex) => (
                        <TableRow key={rowIndex} className="hover:bg-transparent">
                          {preview.importHeaders.map((_, columnIndex) => (
                            <TableCell key={columnIndex} className="truncate p-1.5 text-muted-foreground" title={row[columnIndex] ?? ""}>
                              {row[columnIndex] ?? ""}
                            </TableCell>
                          ))}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                {preview.importHeaders.length > 1 && (
                  <span className="text-xs text-muted-foreground">{labels.io.mapColumnsHint}</span>
                )}
                <span className="text-xs text-muted-foreground">
                  {labels.io.previewTruncated(previewRows.length, importRows.length)}
                </span>
              </div>
            </>
          )}
        </div>

        <DialogFooter>
          <Button type="button" variant="outline" onClick={onCancel}>
            {labels.io.cancel}
          </Button>
            <Button type="button" onClick={onConfirm} disabled={!preview || importRows.length === 0 || isParsing || isValidating || rejectedCount > 0}>
              {labels.io.import}
            </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { Upload } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { Button } from "@/components/ui/button";
import { DataGridImportDialog, type ImportDefaults } from "./import-dialog";
import type { ImportLimits } from "./parse-import-file";

export type { ImportDefaults };

/** Props for {@link DataGridImportButton}. */
export type DataGridImportButtonProps<TData> = {
  className?: string;
  /** Builds a fresh row for import row `index`; required — the dialog never writes to the grid store directly. */
  createRow: (index: number) => TData;
  /** Called with the fully-built rows on confirm; the consumer decides how to merge (replace/append). */
  onImport: (rows: TData[]) => void | Promise<void>;
  /** Consumer-configurable preselection defaults (delimiter, header row, skip columns, mapping). Omit for today's behavior unchanged. */
  importDefaults?: ImportDefaults;
  /** Size, row, column, cell, and unpacked-size bounds for the file; omitted fields use `DEFAULT_IMPORT_LIMITS`. `maxFileBytes` also sets the drop zone's `maxSize`. */
  importLimits?: ImportLimits;
};

/**
 * Toolbar-slot import trigger: a ghost icon button that opens {@link DataGridImportDialog}.
 * `size-8` + ghost variant matches the toolbar's other icon buttons.
 */
export function DataGridImportButton<TData>(props: DataGridImportButtonProps<TData>): ReactNode {
  const { className, createRow, onImport, importDefaults, importLimits } = props;
  const labels = useDataGridLabels();
  const [open, setOpen] = useState(false);

  return (
    <>
      <Button type="button" variant="ghost" size="icon" className={className} aria-label={labels.io.importButton} onClick={() => setOpen(true)}>
        <Upload />
      </Button>
      <DataGridImportDialog open={open} onOpenChange={setOpen} createRow={createRow} onImport={onImport} importDefaults={importDefaults} importLimits={importLimits} />
    </>
  );
}
